    function objectBox(o){if(['ecology-node','ecology-zone','ecology-pyramid','ecology-label'].includes(o.type))return{x:o.x,y:o.y,w:o.width,h:o.height};if(['ecology-link','ecology-arrow'].includes(o.type))return{x:Math.min(o.x1||0,o.x2||0),y:Math.min(o.y1||0,o.y2||0),w:Math.max(1,Math.abs((o.x2||0)-(o.x1||0))),h:Math.max(1,Math.abs((o.y2||0)-(o.y1||0)))};if(o.type==='text')return{x:o.x,y:o.y-o.fontSize,w:Math.max(100,String(o.text||'').length*o.fontSize*.55),h:o.fontSize+10};return null;}
    function portPoint(o,port){const b=objectBox(o)||{x:0,y:0,w:0,h:0};const map={n:[.5,0],ne:[1,0],e:[1,.5],se:[1,1],s:[.5,1],sw:[0,1],w:[0,.5],nw:[0,0]};const[px,py]=map[port]||map.e;return{x:b.x+b.w*px,y:b.y+b.h*py};}
    function pointerPoint(event){const rect=state.svg.getBoundingClientRect(),vb=state.svg.viewBox.baseVal;return{x:(event.clientX-rect.left)*vb.width/rect.width+vb.x,y:(event.clientY-rect.top)*vb.height/rect.height+vb.y};}
    function findObjectFromTarget(target){const hit=target.closest?.('[data-ecology-hit-object]');if(hit)return objectById(hit.getAttribute('data-ecology-hit-object'));const node=target.closest?.('[data-qmx-object]');return node?objectById(node.getAttribute('data-qmx-object')):null;}
    function createToolObject(tool,p){if(NODE_KINDS.includes(tool))return makeNode(tool,{x:snap(p.x-75),y:snap(p.y-48)});if(tool==='ecosystem-zone')return makeZone({x:snap(p.x-250),y:snap(p.y-170)});if(PYRAMID_KINDS.includes(tool))return makePyramid(tool,{x:snap(p.x-270),y:snap(p.y-280)});if(tool==='process-arrow')return makeArrow({x1:snap(p.x-140),y1:snap(p.y),x2:snap(p.x+140),y2:snap(p.y)});if(tool==='text')return makeText({x:snap(p.x),y:snap(p.y)});return null;}
    function selectionMarkup(){const parts=[];if(state.activeTool==='select')state.document.objects.forEach((o)=>{const id=esc(o.id),b=objectBox(o);if(['ecology-link','ecology-arrow'].includes(o.type)){const a=resolveLinkEndpoints(o);parts.push(`<line class="qmx-ecology-hit" data-ecology-hit-object="${id}" x1="${a.x1}" y1="${a.y1}" x2="${a.x2}" y2="${a.y2}" stroke="transparent" stroke-width="24" pointer-events="stroke"/>`);}else if(b)parts.push(`<rect class="qmx-ecology-hit" data-ecology-hit-object="${id}" x="${b.x}" y="${b.y}" width="${Math.max(12,b.w)}" height="${Math.max(12,b.h)}" fill="transparent" stroke="none" pointer-events="all"/>`);});if(['smart-label','smart-link'].includes(state.activeTool))targetObjects().forEach((o)=>PORTS.forEach((port)=>{const p=portPoint(o,port),active=(state.labelStart?.objectId===o.id&&state.labelStart?.port===port)||(state.linkStart?.objectId===o.id&&state.linkStart?.port===port);parts.push(`<circle data-ecology-target="${esc(o.id)}" data-ecology-port="${port}" cx="${p.x}" cy="${p.y}" r="7.5" fill="${active?'#f59e0b':'#22c55e'}" stroke="#fff" stroke-width="2" style="cursor:crosshair"/>`);}));const o=selectedObject(),b=o&&objectBox(o);if(b)parts.push(`<rect x="${b.x-7}" y="${b.y-7}" width="${Math.max(14,b.w+14)}" height="${Math.max(14,b.h+14)}" fill="none" stroke="#2563eb" stroke-width="2" stroke-dasharray="7 5" pointer-events="none"/>`);return parts.join('');}
    function resolveLinkEndpoints(o){const source=objectById(o.sourceId),target=objectById(o.targetId),a=source?portPoint(source,o.sourcePort):{x:o.x1||0,y:o.y1||0},b=target?portPoint(target,o.targetPort):{x:o.x2||0,y:o.y2||0};return{x1:a.x,y1:a.y,x2:b.x,y2:b.y};}
    function render(){if(!state.canvas||!state.document)return;state.document=Diagram.normalizeSpec(state.document);let svg=Diagram.svgMarkup(state.document);svg=svg.replace('</svg>',`${selectionMarkup()}</svg>`);state.canvas.innerHTML=svg;state.svg=state.canvas.querySelector('svg');syncSelectedControls();updateSummary();}
