    function restoreHistory(index){if(index<0||index>=state.history.length)return;state.historyIndex=index;state.document=Diagram.normalizeSpec(JSON.parse(state.history[index]));state.selectedId=null;state.labelStart=null;state.linkStart=null;state.interaction=null;syncDocumentControls();render();updateHistoryButtons();}
    function undo(){restoreHistory(state.historyIndex-1);}function redo(){restoreHistory(state.historyIndex+1);}function updateHistoryButtons(){if(state.controls.undo)state.controls.undo.disabled=state.historyIndex<=0;if(state.controls.redo)state.controls.redo.disabled=state.historyIndex>=state.history.length-1;}
