    function syncDocumentControls(){if(!state.root||!state.document)return;state.root.querySelectorAll('[data-doc]').forEach((input)=>{const key=input.dataset.doc;if(input.type==='checkbox')input.checked=Boolean(state.document[key]);else input.value=state.document[key]??'';});}
    function onRootChange(event){const docInput=event.target.closest?.('[data-doc]');if(docInput){const key=docInput.dataset.doc;state.document[key]=docInput.type==='checkbox'?docInput.checked:(docInput.type==='number'?num(docInput.value,state.document[key]):docInput.value);pushHistory();render();return;}const prop=event.target.closest?.('[data-prop]');if(!prop)return;const o=selectedObject();if(!o)return;const key=prop.dataset.prop;o[key]=prop.type==='checkbox'?prop.checked:(prop.type==='number'?num(prop.value,o[key]):prop.value);if(o.type==='ecology-node'&&key==='kind'){const [fill,stroke]=nodeStyle(o.kind),[width,height]=defaultSize(o.kind);o.fill=fill;o.stroke=stroke;o.width=width;o.height=height;o.label=o.kind.replace(/-/g,' ');}if(o.type==='ecology-pyramid'&&key==='kind'){const n=makePyramid(o.kind);o.title=n.title;o.unit=n.unit;}pushHistory();render();}
    function deleteSelected(){const o=selectedObject();if(!o)return;const id=o.id;state.document.objects=state.document.objects.filter((x)=>x.id!==id&&!(x.type==='ecology-label'&&x.targetId===id)&&!(x.type==='ecology-link'&&(x.sourceId===id||x.targetId===id)));state.selectedId=null;pushHistory();render();setStatus('Selected object deleted.');}
    function duplicateSelected(){const o=selectedObject();if(!o)return;const c=clone(o);c.id=uid(o.type);if('x'in c)c.x+=30;if('y'in c)c.y+=30;if('x1'in c){c.x1+=30;c.x2+=30;c.y1+=30;c.y2+=30;}if(c.type==='ecology-label')c.targetId='';if(c.type==='ecology-link'){c.sourceId='';c.targetId='';}state.document.objects.push(c);state.selectedId=c.id;pushHistory();render();}
