    function onCanvasPointerDown(event){if(!state.svg||event.button>0)return;const handle=event.target.closest?.('[data-ecology-target]');if(handle&&state.activeTool==='smart-label'){state.labelStart={objectId:handle.dataset.ecologyTarget,port:handle.dataset.ecologyPort};setStatus('Target point selected. Click where the label should appear.');render();event.preventDefault();return;}if(handle&&state.activeTool==='smart-link'){if(!state.linkStart){state.linkStart={objectId:handle.dataset.ecologyTarget,port:handle.dataset.ecologyPort};setStatus('Source selected. Click a target connection point.');render();}else{const targetId=handle.dataset.ecologyTarget,targetPort=handle.dataset.ecologyPort;if(targetId!==state.linkStart.objectId){const link=makeLink(state.linkStart.objectId,state.linkStart.port,targetId,targetPort);state.document.objects.push(link);state.selectedId=link.id;state.linkStart=null;pushHistory();setTool('select',false);render();setStatus('Smart ecological link created.');}}event.preventDefault();return;}const p=pointerPoint(event);if(state.activeTool==='smart-label'&&state.labelStart){const target=objectById(state.labelStart.objectId);if(target){const l=makeLabel(target.id,state.labelStart.port,{x:snap(p.x),y:snap(p.y),text:target.label||target.kind||'Ecological component'});state.document.objects.push(l);state.selectedId=l.id;state.labelStart=null;pushHistory();setTool('select',false);render();setStatus('Smart label created.');}event.preventDefault();return;}if(state.activeTool!=='select'){const o=createToolObject(state.activeTool,p);if(o){state.document.objects.push(o);state.selectedId=o.id;pushHistory();setTool('select',false);render();setStatus('Object added and selected.');}event.preventDefault();return;}const o=findObjectFromTarget(event.target);if(!o){state.selectedId=null;render();return;}state.selectedId=o.id;const b=objectBox(o),resolved=['ecology-link'].includes(o.type)?resolveLinkEndpoints(o):null;state.interaction={id:o.id,pointerId:event.pointerId,start:p,origin:b?{x:b.x,y:b.y}:null,line:['ecology-link','ecology-arrow'].includes(o.type)?{x1:resolved?.x1??o.x1,y1:resolved?.y1??o.y1,x2:resolved?.x2??o.x2,y2:resolved?.y2??o.y2}:null,moved:false};render();setStatus('Object selected. Drag anywhere inside its blue selection area to move.');event.preventDefault();}
    function onPointerMove(event){if(!state.interaction||!state.svg||event.pointerId!==state.interaction.pointerId)return;const o=objectById(state.interaction.id);if(!o)return;const p=pointerPoint(event),dx=p.x-state.interaction.start.x,dy=p.y-state.interaction.start.y;if(Math.abs(dx)+Math.abs(dy)<1)return;state.interaction.moved=true;if(['ecology-link','ecology-arrow'].includes(o.type)){if(o.type==='ecology-link'){o.sourceId='';o.targetId='';}o.x1=snap(state.interaction.line.x1+dx);o.x2=snap(state.interaction.line.x2+dx);o.y1=snap(state.interaction.line.y1+dy);o.y2=snap(state.interaction.line.y2+dy);}else if('x'in o&&'y'in o&&state.interaction.origin){o.x=snap(state.interaction.origin.x+dx);o.y=snap(state.interaction.origin.y+dy);}render();event.preventDefault();}
