    function onKeydown(event){if(state.root?.hidden)return;if(event.key==='Escape'){if(state.labelStart||state.linkStart){state.labelStart=null;state.linkStart=null;render();}else close();}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo();}else if(event.key==='Delete'||event.key==='Backspace'){const tag=event.target?.tagName;if(!['INPUT','TEXTAREA','SELECT'].includes(tag)){event.preventDefault();deleteSelected();}}}
