    function buildEditor(){if(state.root)return;addStyles();const root=document.createElement('div');root.className='qmx-ecology-editor';root.hidden=true;root.innerHTML=`<div class="qmx-ecology-shell" role="dialog" aria-modal="true" aria-label="Ecology, food chain and ecosystem diagram editor"><header class="qmx-ecology-header"><div><div class="qmx-ecology-title">Ecology / Food Chain & Ecosystem Diagram</div><div class="qmx-ecology-subtitle">Food chains, food webs, trophic levels, ecological pyramids and biogeochemical cycles</div></div><div class="qmx-ecology-actions"><button class="qmx-ecology-btn" data-ecology="new">New</button><button class="qmx-ecology-btn" data-ecology="undo">Undo</button><button class="qmx-ecology-btn" data-ecology="redo">Redo</button><button class="qmx-ecology-btn" data-ecology="duplicate">Duplicate</button><button class="qmx-ecology-btn danger" data-ecology="delete">Delete</button><button class="qmx-ecology-btn" data-ecology="close">×</button></div></header><main class="qmx-ecology-main"><aside class="qmx-ecology-panel"><strong>Ecology tools</strong><div class="qmx-ecology-tools" data-tools></div><div class="qmx-ecology-section">Ecosystem presets</div><div class="qmx-ecology-presets"><button class="qmx-ecology-preset" data-preset="grassland-chain">Grassland chain</button><button class="qmx-ecology-preset" data-preset="pond-web">Pond food web</button><button class="qmx-ecology-preset" data-preset="forest">Forest ecosystem</button><button class="qmx-ecology-preset" data-preset="energy-pyramid">Energy pyramid</button><button class="qmx-ecology-preset" data-preset="biomass-pyramid">Biomass pyramid</button><button class="qmx-ecology-preset" data-preset="carbon-cycle">Carbon cycle</button><button class="qmx-ecology-preset" data-preset="nitrogen-cycle">Nitrogen cycle</button><button class="qmx-ecology-preset" data-preset="water-cycle">Water cycle</button><button class="qmx-ecology-preset" data-preset="succession">Ecological succession</button><button class="qmx-ecology-preset" data-preset="clear">Clear</button></div><p class="qmx-ecology-subtitle">Smart link: click a source port and then a target port. Links stay attached while nodes move.</p></aside><section class="qmx-ecology-canvas-wrap"><div class="qmx-ecology-canvas" data-canvas></div></section><aside class="qmx-ecology-panel"><strong>Document</strong><div class="qmx-ecology-field"><label>Title</label><input data-doc="title"></div><div class="qmx-ecology-grid2"><div class="qmx-ecology-field"><label>Width</label><input type="number" min="600" max="2400" data-doc="width"></div><div class="qmx-ecology-field"><label>Height</label><input type="number" min="400" max="1800" data-doc="height"></div><div class="qmx-ecology-field"><label>Grid size</label><input type="number" min="5" max="100" data-doc="gridSize"></div><div class="qmx-ecology-field"><label>Background</label><input type="color" data-doc="background"></div></div><label class="qmx-ecology-check"><input type="checkbox" data-doc="ecologyShowGrid"> Show grid</label><label class="qmx-ecology-check"><input type="checkbox" data-doc="ecologyShowLabels"> Show smart labels</label><label class="qmx-ecology-check"><input type="checkbox" data-doc="ecologyShowEnergy"> Show link energy / values</label><label class="qmx-ecology-check"><input type="checkbox" data-doc="ecologyShowZones"> Show ecosystem zones</label><label class="qmx-ecology-check"><input type="checkbox" data-doc="ecologyShowTrophicLevels"> Show trophic levels</label><label class="qmx-ecology-check"><input type="checkbox" data-doc="snap"> Snap to grid</label><hr><strong>Selected object</strong><div data-selected></div><div class="qmx-ecology-summary" data-summary></div></aside></main><footer class="qmx-ecology-footer"><div class="qmx-ecology-status" data-status></div><div class="qmx-ecology-actions"><button class="qmx-ecology-btn" data-ecology="export-svg">Export SVG</button><button class="qmx-ecology-btn" data-ecology="export-png">Export PNG</button><button class="qmx-ecology-btn primary" data-ecology="insert">Insert into question</button></div></footer></div>`;document.body.appendChild(root);state.root=root;state.canvas=root.querySelector('[data-canvas]');state.controls={tools:root.querySelector('[data-tools]'),selected:root.querySelector('[data-selected]'),summary:root.querySelector('[data-summary]'),status:root.querySelector('[data-status]'),undo:root.querySelector('[data-ecology="undo"]'),redo:root.querySelector('[data-ecology="redo"]')};TOOL_DEFS.forEach(([id,label,bn])=>{const b=document.createElement('button');b.className='qmx-ecology-tool';b.dataset.tool=id;b.innerHTML=window.QmxDiagramToolButtonContent?window.QmxDiagramToolButtonContent(id,label,bn):`${esc(label)}<small>${esc(bn)}</small>`;state.controls.tools.appendChild(b);});root.addEventListener('click',onRootClick);root.addEventListener('change',onRootChange);state.canvas.addEventListener('pointerdown',onCanvasPointerDown);document.addEventListener('pointermove',onPointerMove,{passive:false});document.addEventListener('pointerup',onPointerUp);document.addEventListener('pointercancel',onPointerUp);document.addEventListener('focusin',(event)=>{if(isUsableTextarea(event.target))lastExternalTextarea=event.target;},true);document.addEventListener('keydown',onKeydown);}
    function open(context={}){buildEditor();state.context=context||{};state.sourceTextarea=resolveQuestionTextarea(state.context);state.document=state.context.initialSpec?Diagram.normalizeSpec(state.context.initialSpec):createDocument();if(state.document.mode!=='ecology-diagram')state.document=createDocument();state.selectedId=null;state.activeTool='select';state.interaction=null;state.labelStart=null;state.linkStart=null;state.history=[];state.historyIndex=-1;pushHistory();syncDocumentControls();setTool('select',false);render();state.root.hidden=false;document.body.dataset.qmxEcologyOverflow=document.body.style.overflow||'';document.body.style.overflow='hidden';setStatus(state.context.initialSpec?'Existing ecology diagram loaded.':'Choose an ecosystem component, smart link, pyramid, label, process arrow or preset.');}
    function close(){if(!state.root)return;state.root.hidden=true;document.body.style.overflow=document.body.dataset.qmxEcologyOverflow||'';delete document.body.dataset.qmxEcologyOverflow;state.labelStart=null;state.linkStart=null;state.interaction=null;}
    function findTokenTextarea(token){return Array.from(document.querySelectorAll('textarea')).find((t)=>t.value.includes(token))||null;}
    function openFromPreview(figure){const payload=String(figure?.dataset.qmxDiagramPayload||'');if(!payload)return false;let spec;try{spec=Diagram.decodePayload(payload);}catch(error){return false;}if(spec.mode!=='ecology-diagram')return false;const token=`[[qmx-diagram:${payload}]]`;const textarea=findTokenTextarea(token)||window.QmxDiagramLauncher?.getActiveTextarea?.();let replaceRange=null;if(textarea){const start=textarea.value.indexOf(token);if(start>=0)replaceRange={start,end:start+token.length};}open({tool:{id:'ecology-diagram'},textarea,initialSpec:spec,replaceRange,editMode:true});return true;}
    function registerHandlers(){const launcher=window.QmxDiagramLauncher;if(!launcher?.registerToolHandler)return false;let registered=false;['ecology-diagram','food-chain','food-web','ecosystem-diagram','ecological-pyramid'].forEach((id)=>{try{launcher.registerToolHandler(id,open);registered=true;}catch(error){}});return registered;}
    buildEditor();registerHandlers();document.addEventListener('qmx:diagram-launcher-ready',registerHandlers);
    window.QmxEcologyEditor=Object.freeze({version:'1.0.0',open,close,openFromPreview});
